  "q": "Un estudiante lee que Carnap criticó la metafísica porque frases como «la nada misma nadea» no son comprobables ni verdades lógicas. Su profesor le responde que el criterio de Carnap, «solo tiene sentido lo comprobable por la experiencia», tampoco es comprobable por la experiencia. ¿Qué se sigue de esa respuesta?",
